-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warrior.dps.Name"] = "Nahkampf-DPS"
L["rm.era.warrior.dps.Description"] = "Stufen 1–60, Waffen und Furor und jeder Krieger außerhalb der Verteidigungshaltung, auch auf Hardcore- und Self-Found-Realms; zusammengestellt aus Simulation, Icy Veins und Wowhead. Sturmangriff zum Ziehen, Abfangen gegen ein entferntes Ziel, Wirbelwind (Donnerknall, bevor Sie ihn erlernen), wenn drei oder mehr Gegner gegen Sie kämpfen, dann Hinrichten zuerst unter 20 %, Rüstung zerreißen bis fünf Stapel gegen Bosse ohne Rüstung schwächen, Blutdurst, Tödlicher Stoß, Zerschmettern direkt nach einem Schlag mit Verbessertem Zerschmettern (eingestellt für eine Zweihandwaffe; ändern Sie es in einer Kopie), Wirbelwind, während Wut für Ihren Hauptangriff zurückgehalten wird, Überwältigen, Verwunden, bis Ihr Hauptangriff erlernt ist, Rüstung zerreißen auf Zielen mit viel Gesundheit und Kniesehne nahe der maximalen Wut. Erinnerungen: Schlachtruf, Heldenhafter Stoß ab 40 Wut (20 beim Leveln), Spalten gegen Gruppen, Blutrausch, Weitreichende Stöße, Todeswunsch (bei Bossen: in ihren letzten 30 Sekunden), Tollkühnheit mit Todeswunsch, Zuschlagen oder Schildhieb. Drohruf und Gegenschlag sind für Hardcore-Notfälle als deaktivierte Schritte aufgeführt; Haltungswechsel bleiben Ihnen überlassen."
L["rm.era.warrior.protection.Name"] = "Tank"
L["rm.era.warrior.protection.Description"] = "Gewählt, wann immer Sie in Verteidigungshaltung sind (Schutz, Furor-Schutz oder ein Tank mit Zweihandwaffe); zusammengestellt aus Icy Veins und MaxDps. Gegen vier oder mehr Gegner: Demoralisierungsruf und Schlachtruf für Bedrohung. Dann Rache, Schildschlag, Blutdurst, Rüstung zerreißen bis fünf Stapel, Demoralisierungsruf gegen Elitegegner, Rüstung zerreißen als Füller und Verwunden, bevor Schildschlag oder Blutdurst erlernt ist. Schildschlag und Schildblock nur mit angelegtem Schild. Erinnerungen: Schlachtruf, Schildblock, während das Ziel Sie trifft, Blutrausch, Heldenhafter Stoß und Spalten ab 50 Wut, Schildhieb, Letztes Gefecht. Spott, Schildwall und Todeswunsch sind als deaktivierte Schritte aufgeführt; Kampfhaltung für Hinrichten (die integrierte DPS-Rotation übernimmt) und Herausforderungsruf bleiben Ihnen überlassen."
L["rm.era.warrior.protection.icyveins.Name"] = "Tank, Bedrohung durch Schlachtruf (Icy Veins)"
L["rm.era.warrior.protection.icyveins.Description"] = "Tanken ohne Rüstung zerreißen nach Icy Veins für Gruppen, in denen vier oder mehr Spieler Ihren Ruf erhalten (Schlachtruf ab Phase 5), eine Alternative zur empfohlenen integrierten Tankrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Demoralisierungsruf aufrechterhalten, Rache, Schildschlag oder Blutdurst, dann Schlachtruf als Bedrohungsfüller statt Rüstung zerreißen; Schildschlag und Schildblock nur mit angelegtem Schild. Dieselben Erinnerungen wie der empfohlene Tank; kehren Sie zu Rüstung zerreißen zurück, wenn Sie in einer Gruppe von Gegnern ein Ziel fokussieren."
L["rm.forever.warrior.dps.Name"] = "Waffen und Furor (Icy Veins)"
L["rm.forever.warrior.dps.Description"] = "Waffen und Furor im Nahkampf von Stufe 1 bis 60 und der Standard für jeden Krieger außerhalb der Verteidigungshaltung. Wut ist unter Forever knapp und für Addons verborgen, daher spart sie, indem sie für alles andere nur Wut ausgibt, solange Tödlicher Stoß oder Blutdurst regeneriert: Sturmangriff zum Pullen, Siegesrausch, Abfangen, Hinrichten (in Reichweite) gegen Elitegegner, Bosse oder in einer Gruppe, Wirbelwind oder Donnerknall, Demoralisierender Ruf und Zerschmettern gegen Gruppen, Aufspießender Stoß gegen Riesen und Drachkin, Verwunden bis Blutdurst, Überwältigen, Tödlicher Stoß, Blutdurst, dann Wirbelwind, Zerschmettern im Stehen und zweimal Rüstung zerreißen (fünfmal gegen Elitegegner). Erinnerungen: Schlachtruf, Blutrausch, die Unterbrechung, Heldenhafter Stoß, solange der Hauptangriff regeneriert, Spalten gegen Gruppen, Weitreichende Stöße, Todeswunsch und Berserkerwut; Tollkühnheit und Gegenschlag sind aufgeführt, aber deaktiviert. Ihnen überlassen: Haltungswechsel, Kniesehne und Verbrauchsgüter."
L["rm.forever.warrior.dps.warcrafttavern.Name"] = "Waffen und Furor, Wut ausgeben (Warcraft Tavern)"
L["rm.forever.warrior.dps.warcrafttavern.Description"] = "Immer-ausgeben-Liste von Warcraft Tavern für Gruppen und Schlachtzüge: zuerst fünfmal Rüstung zerreißen, Hinrichten unter 20 % vor allem anderen, Überwältigen, Verwunden bis Blutdurst, Tödlicher Stoß, Blutdurst, Wirbelwind, Aufspießender Stoß bei Abklingzeit-Ende, Zerschmettern, sobald Verbessertes Zerschmettern gewählt ist; Heldenhafter Stoß oder Spalten, wann immer Sie es sich leisten können (Wut ist unter Forever verborgen, daher gibt es keine Schwelle von 60 Wut und keine Kniesehne bei überschüssiger Wut), Tollkühnheit bei Abklingzeit-Ende mit Todeswunsch daneben. Wählen Sie diese statt der integrierten Rotation nach Icy Veins, wenn Sie in Gruppen spielen und zwischen Pulls keine Wut sparen müssen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.forever.warrior.protection.Name"] = "Schutz (Icy Veins)"
L["rm.forever.warrior.protection.Description"] = "Tanken, wann immer Sie in Verteidigungshaltung sind, von Stufe 10 bis 60. Pullt mit Sturmangriff (in Verteidigungshaltung, sobald Sie Frontkämpfer haben), Siegesrausch und gegen zwei oder mehr Gegner Donnerknall bei Abklingzeit-Ende, Demoralisierender Ruf, Schildschlag, Rache und Verwunden. Gegen ein Ziel: Schildschlag, Rache, Demoralisierender Ruf, Verwunden, Rüstung zerreißen (fünfmal gegen Elitegegner) und Donnerknall gegen gefährliche Ziele. Erinnerungen: Schlachtruf, Blutrausch, Schildhieb, Schildblock, solange Sie das Ziel halten, Heldenhafter Stoß, solange Schildschlag und Rache beide regenerieren, Spalten gegen Gruppen; Spott und Schildwall sind aufgeführt, aber deaktiviert. Wut, Gesundheit und das Mana des Ziels sind für Addons unter Forever verborgen, daher entscheiden Sie selbst über die Wutschwellen, Zauberwirker und Letztes Gefecht. Ihnen überlassen: vor Frontkämpfer in die Kampfhaltung wechseln, um Sturmangriff zu nutzen, andere Gegner verspotten und lose Gegner aufsammeln."
L["rm.forever.warrior.protection.warcrafttavern.Name"] = "Schutz, Schwächungszauber zuerst (Warcraft Tavern)"
L["rm.forever.warrior.protection.warcrafttavern.Description"] = "Tank-Reihenfolge nach Warcraft Tavern: Donnerknall, Demoralisierender Ruf und fünfmal Rüstung zerreißen werden zuerst auf jedem Ziel aufrechterhalten, dann Rache, Verwunden und zuletzt Schildschlag, mit Heldenhaftem Stoß oder Spalten, wann immer Sie es sich leisten können (Wut ist unter Forever verborgen, daher gibt es keine Schwelle von 60 Wut). Keine Erinnerungen an Schildblock oder Defensivfähigkeiten. Wählen Sie diese statt der integrierten Tankrotation nach Icy Veins, wenn Sie lieber zuerst die Schwächungszauber aufrechterhalten. Eine Alternative zur empfohlenen integrierten Schutzrotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.mop.warrior.arms.Name"] = "Empfohlen"
L["rm.mop.warrior.arms.Description"] = "Empfohlen für Waffen von Stufe 10 bis 90, gewählt in der Spezialisierung Waffen. Sturmangriff zum Eröffnen und erneut für Wut, wenn Sie sich entfernen. Kolossales Schmettern, wann immer es fehlt oder bald endet, Tödlicher Stoß, Sturmblitz im Fenster von Kolossales Schmettern, Drachengebrüll und Klingensturm außerhalb davon. Unter 20 % Gesundheit: Hinrichten im Fenster, bei 100 Wut oder um Plötzliches Hinrichten zu halten, Überwältigen bei Verlangen nach Blut. Sonst Zerschmettern im Fenster, Überwältigen bei vier Stapeln, Zerschmettern bei 100 Wut, Überwältigen, Zerschmettern. Wenn zwei oder mehr Gegner gegen Sie kämpfen, kommen Weitreichende Stöße, Donnerknall für Tiefe Wunden, Klingensturm und Drachengebrüll hinzu. Siegesrausch unter 70 % Gesundheit; Schlachtruf für Wut. Erinnerungen: ein Ruf, wenn keiner aktiv ist, Kampfhaltung, Berserkerwut, Tollkühnheit, Avatar und Blutbad mit Kolossales Schmettern bei langen Kämpfen, Schädelbanner, Heldenhafter Stoß oder Spalten bei überschüssiger Wut, Heldenhafter Sprung im Fenster, Zuschlagen, Durch das Schwert umkommen und Wütende Regeneration bei niedriger Gesundheit. Zerschmetternder Wurf ist aufgeführt, aber deaktiviert. Ihnen überlassen: Abbrechen von Klingensturm, Haltungswechsel und Positionierung."
L["rm.mop.warrior.arms.icyveins.Name"] = "Wut für Kolossales Schmettern sammeln (Icy Veins)"
L["rm.mop.warrior.arms.icyveins.Description"] = "Standardmäßig deaktiviert. Die Waffen-Reihenfolge von Icy Veins und Wowhead: Außerhalb des Fensters von Kolossales Schmettern nutzt sie Überwältigen und Zerschmettern nur über 80 Wut und spart Wut für das Fenster auf, statt Zerschmettern als Füller zu nutzen. Im Fenster: Tödlicher Stoß, Zerschmettern, Überwältigen, Heldenhafter Wurf. Unter 20 % Gesundheit: Kolossales Schmettern, Tödlicher Stoß, Hinrichten, Überwältigen, Drachengebrüll. Weitreichende Stöße gegen zwei Gegner, eine Gruppenliste mit Donnerknall ab drei. Heldenhafter Stoß oder Spalten nur nahe der maximalen Wut. Dieselben Erinnerungen wie die empfohlene integrierte Waffen-Rotation. Aktivieren Sie sie und deaktivieren Sie die andere, um sie zu verwenden."
L["rm.mop.warrior.fury.Name"] = "Empfohlen"
L["rm.mop.warrior.fury.Description"] = "Empfohlen für Furor von Stufe 10 bis 90, gewählt in der Spezialisierung Furor. Sturmangriff zum Eröffnen und für Wut. Kolossales Schmettern, sobald zwei Aufladungen von Wütender Schlag angespart sind (eine mit Tollkühnheit), Wütender Schlag, wenn sich das Fenster schließt, Blutdurst, Kolossales Schmettern, Sturmblitz, Drachengebrüll außerhalb des Fensters, hier Hinrichten mit Zielstrebiger Furor (Einhandwaffen), Klingensturm, während Blutdurst abklingt, mit Titanengriff (Zweihandwaffen) ein weiterer Wütender Schlag außerhalb des Fensters, Hinrichten, Wilder Stoß bei Schäumendes Blut, Wütender Schlag, wobei eine Aufladung für das nächste Fenster bleibt, Wilder Stoß, Heldenhafter Wurf, Schlachtruf für Wut. Wenn zwei oder mehr Gegner gegen Sie kämpfen, kommen Klingensturm, Drachengebrüll, Wirbelwind für Metzger und spaltende Wütende Schläge hinzu. Erinnerungen: ein Ruf, wenn keiner aktiv ist, Kampfhaltung, Berserkerwut für Wutanfall, Tollkühnheit, Avatar und Blutbad mit Kolossales Schmettern bei langen Kämpfen, Schädelbanner, Heldenhafter Stoß oder Spalten bei überschüssiger Wut, Heldenhafter Sprung, Zuschlagen und Defensivfähigkeiten bei niedriger Gesundheit. Ihnen überlassen: Abbrechen von Klingensturm."
L["rm.mop.warrior.fury.icyveins.Name"] = "Abklingzeiten in Kolossales Schmettern (Icy Veins)"
L["rm.mop.warrior.fury.icyveins.Description"] = "Standardmäßig deaktiviert. Die Furor-Reihenfolge von Icy Veins setzt Klingensturm oder Drachengebrüll zuerst im Fenster von Kolossales Schmettern ein und stellt unter 20 % Gesundheit Hinrichten vor Blutdurst. Außerhalb des Fensters: Kolossales Schmettern, Blutdurst, Wütender Schlag nur bei zwei Aufladungen, Wilder Stoß bei Schäumendes Blut, Ruf, Wilder Stoß. Vier oder mehr Gegner: Blutdurst für Wutanfall, Wirbelwind bis drei Stapel Metzger, Wütender Schlag. Heldenhafter Stoß oder Spalten nur nahe der maximalen Wut. Dieselben Erinnerungen wie die empfohlene integrierte Furor-Rotation. Aktivieren Sie sie und deaktivieren Sie die andere, um sie zu verwenden."
L["rm.mop.warrior.protection.Name"] = "Empfohlen"
L["rm.mop.warrior.protection.Description"] = "Tanken von Stufe 10 bis 90, gewählt in der Spezialisierung Schutz. Sturmangriff oder Heldenhafter Wurf zum Ziehen. Verwüsten, um drei Stapel Rüstungsschwächung auf Elitegegnern und Bossen zu halten, Drachengebrüll, Klingensturm, Schockwelle gegen drei Gegner und Donnerknall bei Abklingzeit-Ende gegen drei oder mehr. Dann Rache für die letzte Wut eines Schildblocks, Schildschlag, Rache bei Stellung halten, Verwüsten für Tiefe Wunden, Siegesrausch unter 60 % Gesundheit, Rache, Donnerknall für Kampfesmüdigkeit, Hinrichten, Sturmblitz, ein Ruf für Wut und Verwüsten (Rüstung zerreißen vor Stufe 26). Erinnerungen: Verteidigungshaltung, ein Ruf, wenn keiner aktiv ist, Schildblock, wann immer er fehlt, Schildbarriere bei Verletzung mit überschüssiger Wut, Heldenhafter Stoß oder Spalten bei Ultimatum, Anstacheln oder nahe der maximalen Wut, Demoralisierender Ruf, Berserkerwut, Wütende Regeneration, Letztes Gefecht und Schildwall bei niedriger Gesundheit, Ihre offensiven Abklingzeiten, Zuschlagen. Spott und Heldenhafter Sprung sind aufgeführt, aber deaktiviert. Ihnen überlassen: wen Sie spotten und Schildblock gegenüber Schildbarriere gegen Magie."
L["rm.mop.warrior.unspecialized.Name"] = "Ohne Spezialisierung"
L["rm.mop.warrior.unspecialized.Description"] = "Für Stufe 1 bis 9 oder bis Sie eine Spezialisierung wählen. Sturmangriff zum Ziehen, Siegesrausch, Hinrichten und Heldenhafter Stoß, wenn Sie 30 Wut haben; erinnert Sie daran, in Kampfhaltung zu sein, wenn Sie in keiner Haltung sind."
L["rm.retail.warrior.arms.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warrior.arms.Description"] = "Empfohlen für Waffen in Midnight. Im Kampf verbirgt das Spiel nun Wut, Verwunden, Kolossales Schmettern, Procs, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Heldenhafter Stoß (eine Kernfähigkeit, die der Vorschlag nie nutzt), Avatar und Speer des Champions im Kampf, Schlachtruf zwischen den Kämpfen, Zuschlagen bei einem unterbrechbaren Zauber (es leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt), Durch das Schwert umkommen, wann immer es im Kampf bereit ist (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen)."
L["rm.retail.warrior.arms.colossus.Name"] = "Koloss-Referenz (SimulationCraft)"
L["rm.retail.warrior.arms.colossus.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Koloss-Reihenfolge von SimulationCraft und Icy Veins baut Kolossale Macht mit Tödlichem Stoß auf und liest Stärkungszauber, die Midnight im Kampf verbirgt. Sturmangriff zum Eröffnen; Weitreichende Stöße gegen zwei oder mehr; Tödlicher Stoß unter fünf Stapeln Kolossale Macht; Verwunden vor Kolossalem Schmettern; Verheerer; Hinrichten bei zwei Stapeln Plötzlicher Tod; Kolossales Schmettern; Speer des Champions; Demolieren während Kolossalem Schmettern mit Kolossaler Macht; Heldenhafter Stoß; Tödlicher Stoß; Hinrichten; Überwältigen; Verwunden unter 5 Sekunden; Klingensturm gegen zwei oder mehr; Zerschmettern. Erinnerungen: Avatar, Durch das Schwert umkommen, Schlachtruf, Zuschlagen."
L["rm.retail.warrior.arms.slayer.Name"] = "Schlächter-Referenz (SimulationCraft)"
L["rm.retail.warrior.arms.slayer.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Schlächter-Reihenfolge von SimulationCraft, Icy Veins und Wowhead liest Wut, Verwunden, Kolossales Schmettern, Plötzlichen Tod und Opportunist, die Midnight im Kampf verbirgt. Sturmangriff zum Eröffnen; Weitreichende Stöße gegen zwei oder mehr Gegner im Kampf; Verwunden vor Kolossalem Schmettern, wenn es ausläuft; Verheerer kurz vor Kolossalem Schmettern; Hinrichten bei zwei Stapeln Plötzlicher Tod; Kolossales Schmettern; Klingensturm während Kolossalem Schmettern oder Avatar; Heldenhafter Stoß; Überwältigen bei zwei Stapeln Opportunist; Tödlicher Stoß; Hinrichten; Überwältigen; Verwunden unter 5 Sekunden; Zerschmettern. Erinnerungen: Avatar bei bereitem Kolossalem Schmettern, Durch das Schwert umkommen, Schlachtruf, Zuschlagen."
L["rm.retail.warrior.fury.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warrior.fury.Description"] = "Empfohlen für Furor in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (Toben, Blutdurst, Wütender Schlag, Hinrichten, Odyns Zorn und Klingensturm) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Tollkühnheit, Avatar und Speer des Champions im Kampf, Schlachtruf zwischen den Kämpfen, Zuschlagen, Wütende Regeneration, wann immer sie im Kampf bereit ist (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen)."
L["rm.retail.warrior.fury.slayer.Name"] = "Schlächter-Referenz (SimulationCraft)"
L["rm.retail.warrior.fury.slayer.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Schlächter-Reihenfolge von SimulationCraft liest Wutanfall, Tollkühnheit und Plötzlichen Tod, die Midnight im Kampf verbirgt; Wut ist unter Retail verborgen, daher wartet Toben nur auf seine Kosten. Sturmangriff zum Eröffnen; Wirbelwind für den Stärkungszauber gegen zwei oder mehr Gegner im Kampf; Toben, wenn Wutanfall ausläuft; während Tollkühnheit Toben, Klingensturm, Hinrichten bei Plötzlichem Tod, Odyns Zorn; Schmetterschlag; Blutbad; Hinrichten; Odyns Zorn; Wütender Schlag; Toben; Blutdurst; Wirbelwind. Erinnerungen: Tollkühnheit, Avatar, Wütende Regeneration, Schlachtruf, Zuschlagen."
L["rm.retail.warrior.fury.thane.Name"] = "Bergthan-Referenz (Icy Veins)"
L["rm.retail.warrior.fury.thane.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Bergthan-Reihenfolge von SimulationCraft und Icy Veins webt Donnerexplosion ein und liest Stärkungszauber, die Midnight im Kampf verbirgt. Sturmangriff zum Eröffnen; Wirbelwind für den Stärkungszauber gegen zwei oder mehr; Toben, wenn Wutanfall fehlt oder ausläuft (Wut ist unter Retail verborgen, daher gibt es kein Toben bei 100 Wut); Blutbad während Tollkühnheit; Donnerexplosion bei zwei Stapeln; Schmetterschlag; Blutbad; Toben während Tollkühnheit; Donnerexplosion während Avatar; Wütender Schlag; Donnerexplosion; Toben; Blutdurst; Hinrichten; Odyns Zorn; Donnerknall; Wirbelwind. Dieselben Erinnerungen wie die Schlächter-Referenz."
L["rm.retail.warrior.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warrior.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Kriegers meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Krieger-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.warrior.protection.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.warrior.protection.Description"] = "Empfohlen für Schutz in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent für Ihren Schaden und Ihre Bedrohung und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Der Vorschlag wirkt nie Schildblock oder Zähne zusammenbeißen, daher sind beide Erinnerungen, sobald sie nutzbar sind und Ihr Ziel Sie angreift; das Spiel verbirgt Wut, daher leuchtet Zähne zusammenbeißen öfter auf, als Sie es brauchen. Weitere Erinnerungen: Avatar, Demoralisierender Ruf und Speer des Champions im Kampf, Schildwall und Letztes Gefecht, wann immer sie im Kampf bereit sind (die Gesundheit ist unter Retail verborgen, daher bleibt der Zeitpunkt Ihnen überlassen), Spott in einer Gruppe, wenn Ihr Ziel jemand anderen angreift, Schlachtruf zwischen den Kämpfen, Zuschlagen."
L["rm.retail.warrior.protection.icyveins.Name"] = "Referenz (Icy Veins)"
L["rm.retail.warrior.protection.icyveins.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft liest Schildblock, Donnerexplosion und Kolossale Macht, die Midnight im Kampf verbirgt; Wut und Gesundheit sind unter Retail verborgen. Sturmangriff zum Eröffnen; Verheerer; Donnerexplosion bei zwei Stapeln; Demolieren bei fünf Stapeln Kolossale Macht; Schildansturm; Donnerexplosion; Schildschlag; Donnerknall; Hinrichten; Rache; Verwüsten. Erinnerungen: Schildblock, wenn sein Stärkungszauber fehlt und Sie tanken, Zähne zusammenbeißen, Avatar, Demoralisierender Ruf, Speer des Champions, Schildwall und Letztes Gefecht, wann immer sie im Kampf bereit sind, Schlachtruf, Zuschlagen."
L["rm.sod.warrior.dps.Name"] = "Nahkampf-DPS (SoD)"
L["rm.sod.warrior.dps.Description"] = "Saison der Entdeckungen, Stufen 1–60 mit Runen, sobald Sie sie gravieren: Zweihandwaffe, Beidhändigkeit, Gladiator und Leveln sowie jeder Krieger der Saison der Entdeckungen außerhalb der Verteidigungshaltung; zusammengestellt aus Simulation Phase 6 und Wowhead Phase 7/8. Sturmangriff, Siegesrausch, Abfangen, Wirbelwind (davor Donnerknall) gegen zwei oder mehr Gegner, Zerschmettern bei drei Stapeln Wahnsinn, Verwunden aufrechterhalten, Zerschmettern bei Blutwoge (bei Abklingzeit-Ende mit eingravierter Rune „Precise Timing“), Blutdurst, Tödlicher Stoß, Schildschlag (mit einem Schild), Überwältigen; dann Rasanter Schlag, wenn graviert (Zweihandwaffe), sonst Wirbelwind, Wütender Schlag und Verwüsten (davor Rüstung zerreißen); Hinrichten mit 30 Wut oder bei Plötzlicher Tod; Kniesehne nahe der maximalen Wut. Erinnerungen: Schlacht- und Befehlsruf, Heldenhafter Stoß ab 50 Wut (immer, solange Von Wut zerfressen Sie in Wut versetzt), Spalten, Blutrausch, Toben, Todeswunsch, Tollkühnheit, Weitreichende Stöße, Unterbrechungen. Berserkerwut und der kurze Wechsel in die Kampfhaltung für Verlangen nach Blut sind als deaktivierte Schritte aufgeführt."
L["rm.sod.warrior.dps.icyveins.Name"] = "Nahkampf-DPS (SoD, Icy Veins)"
L["rm.sod.warrior.dps.icyveins.Description"] = "Die Furor- und Waffen-Seiten von Icy Veins für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Hinrichten weit oben unter 20 % oder bei Plötzlicher Tod, Zerschmettern bei Blutwoge, Blutdurst oder Tödlicher Stoß, Wirbelwind, Überwältigen, Wütender Schlag, dann Rasanter Schlag und Kniesehne nur über 60 Wut; kein Verwunden; Heldenhafter Stoß nur über 80 Wut. Dieselben Erinnerungen wie die empfohlene integrierte Rotation."
L["rm.sod.warrior.dps.wowhead.Name"] = "Haltungstanz für Kampfvorausseher (SoD, Wowhead)"
L["rm.sod.warrior.dps.wowhead.Description"] = "Die Rotation von Wowhead für Phase 7/8 für Seele des Kampfvoraussehers oder das Sechsteile-Set aus Tier 1 (die Rotation Master nicht erkennen kann), eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Haltungswechsel, um die Stärkungszauber der Vorhersage aufrechtzuerhalten, fast immer Heldenhafter Stoß, dann Blutdurst, Zerschmettern bei Blutwoge, Wirbelwind, Wütender Schlag und Kniesehne; kein Verwunden und kein Überwältigen. Prüfen Sie das Timing der Wechsel im Spiel, bevor Sie sich darauf verlassen."
L["rm.sod.warrior.tank.Name"] = "Tank (SoD)"
L["rm.sod.warrior.tank.Description"] = "Tank in der Saison der Entdeckungen, gewählt in Verteidigungshaltung; zusammengestellt aus Wowhead Phase 8 und Simulation. Sturmangriff; gegen zwei oder mehr Gegner Donnerknall, Schockwelle, Schildschlag, Rache, Wirbelwind und Verwüsten; dann Schildschlag, wann immer Entschluss des Verteidigers fehlt oder ausläuft, Rache, Schildschlag, Schockwelle, Hinrichten, Wirbelwind bei fünf Stapeln Gerissenheit des Gladiators, Verwüsten (davor Rüstung zerreißen), Demoralisierungsruf und Donnerknall gegen Elitegegner, Verwunden, bevor Schildschlag erlernt ist; Schildschlag und Schildblock nur mit angelegtem Schild. Erinnerungen: Schlacht- und Befehlsruf, Schildblock, Heldenhafter Stoß ab 50 Wut, Spalten ab 55, Blutrausch, Toben, Letztes Gefecht, Unterbrechungen. Spott, Schildwall, Todeswunsch, Tollkühnheit und Gegenschlag sind als deaktivierte Schritte aufgeführt; der Wechsel in die Gladiatorhaltung für Hinrichten bleibt Ihnen überlassen."
L["rm.tbc.warrior.dps.icyveins.Name"] = "Nahkampf-DPS (Icy Veins)"
L["rm.tbc.warrior.dps.icyveins.Description"] = "Stufen 1–70, Waffen oder Furor, nach Icy Veins. Derselbe Pull, dieselben Erinnerungen und Leveling-Schritte wie die Simulation-Version, aber mit Tödlichem Stoß kommt Hinrichten zuerst, mit Blutdurst kommt Hinrichten direkt danach, Wirbelwind folgt, ohne Wut zurückzuhalten, und Kniesehne nur bei fast voller Wut. Timing von Zerschmettern, Haltungswechsel und Berserkerwut bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation nach Simulation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.tbc.warrior.dps.simulator.Name"] = "Nahkampf-DPS (Simulation)"
L["rm.tbc.warrior.dps.simulator.Description"] = "Stufen 1–70, Waffen oder Furor. Pullt mit Sturmangriff, dann Siegesrausch, Abfangen, Toben und Wirbelwind, wenn zwei oder mehr Gegner gegen Sie kämpfen (Donnerknall, bevor es erlernt ist). Mit Blutdurst oder Tödlichem Stoß: dieser Angriff, Wirbelwind bei überschüssiger Wut, Hinrichten, Überwältigen. Davor: Wirbelwind, Hinrichten, Überwältigen, Verwunden. Überschüssige Wut geht in Verwüsten oder Rüstung zerreißen, dann Kniesehne. Erinnert an Schlachtruf, Blutrausch, Heldenhaften Stoß oder Spalten zum Wutabbau, Weitreichende Stöße, Todeswunsch, Tollkühnheit und Unterbrechungen. Timing von Zerschmettern, Haltungswechsel und Berserkerwut bleiben Ihnen überlassen."
L["rm.tbc.warrior.protection.icyveins.Name"] = "Tank (Icy Veins)"
L["rm.tbc.warrior.protection.icyveins.Description"] = "Stufen 10–70, gewählt, solange Sie in Verteidigungshaltung sind, nach Icy Veins. Schildschlag, Rache, dann Verwüsten oder Rüstung zerreißen, mit Verwunden zu Kampfbeginn, bis Schildschlag erlernt ist. Gegen Gruppen: Donnerknall und gegen Elitegegner Demoralisierender Ruf. An Schildblock wird erinnert, wann immer Ihr Ziel Sie angreift und Sie einen Schild tragen. Spotten und andere Hilfsmittel bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Tankrotation nach Wowhead, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität."
L["rm.tbc.warrior.protection.wowhead.Name"] = "Tank (Wowhead)"
L["rm.tbc.warrior.protection.wowhead.Description"] = "Stufen 10–70, gewählt, solange Sie in Verteidigungshaltung sind. Schildschlag, Rache, Donnerknall und Demoralisierender Ruf werden gegen Elitegegner und Bosse aufrechterhalten, dann Verwüsten oder Rüstung zerreißen. Gegen Gruppen: zuerst Donnerknall und Demoralisierender Ruf. Erinnert an Schildblock (mit angelegtem Schild) gegen Bosse und höherstufige Gegner, Heldenhaften Stoß oder Spalten, Schlachtruf, Blutrausch, Schildhieb sowie Letztes Gefecht und Schildwall im Notfall. Spotten und andere Hilfsmittel bleiben Ihnen überlassen."
